def img(name,caption='',crop='contain'):return {'type':'image','file':'assets/images/'+name,'caption':caption,'crop':crop}
def eq(text,caption='Explanatory equation'):return {'type':'equation','text':text,'caption':caption}
def table(headers,rows,caption='Explanatory comparison'):return {'type':'table','headers':headers,'rows':rows,'caption':caption}
def code(text,caption='Inspected implementation excerpt'):return {'type':'code','text':text,'caption':caption}
def flow(nodes,caption='Explanatory diagram'):return {'type':'flow','nodes':nodes,'caption':caption}
def d(label,question,answer,reason,visual,sources,locator='',uncertainty='',kind='Project evidence'):
 return dict(label=label,question=question,answer=answer,reason=reason,visual=visual,sources=sources.split(),locator=locator,uncertainty=uncertainty,kind=kind,return_line="That answers the detail. I'll return to the main slide.")
def slide(n,title,section,duration,message,layout,visual,points,script,transition,details,hook='',silence=0,video=None):
 return dict(id=f's{n:02}',title=title,section=section,duration=duration,message=message,layout=layout,visual=visual,points=points,script=script,transition=transition,details=details,hook=hook,silence=silence,video=video)
SLIDES=[]
def add(*args,**kwargs):SLIDES.append(slide(*args,**kwargs))

add(1,'From research to real robots','Introduction',25,
'I turn a robotics idea into a system I can measure and improve.','hero',{'type':'hero-pair'},
['**Understand** the task','**Build** the full chain','**Measure** what happens'],
"Thank you for meeting with me again. I'd like to show how I approach a robotics problem: understand the task, make decisions, build the system, and measure its behavior. I'll focus on my completed work in Singapore.",
"Then I'll connect it to industrial automation and my current project.",[
 d('My background','What prepared you for this work?',
   "My preparatory classes gave me a strong scientific foundation through intensive math, physics, and engineering science. At Arts et Métiers, I learned how industrial processes work and what constraints matter in practice. That helped me recognize opportunities for automation, like the pouring task in my FANUC project. I also built foundations in mechanics, modeling, and control. I then joined a research master's program at Sorbonne Université to strengthen the foundations of robotics.",
   ['Preparatory classes: a strong foundation in math, physics, and engineering science.',
    'Arts et Métiers: industrial processes and constraints, automation opportunities, and foundations in mechanics, modeling, and control.',
    'Sorbonne Université: a research master to strengthen the foundations of robotics.'],
   {'type':'education-pillars','stages':[
     {'name':'Preparatory classes','headline':'Strong scientific foundation','details':['Intensive math, physics & engineering science']},
     {'name':'Arts et Métiers','headline':'Industrial & mechanical engineering','details':['Industrial processes & constraints','Automation & control fundamentals']},
     {'name':'Sorbonne Université','headline':'Research master in robotics','details':['Strengthening the foundations of robotics']}
   ]},'USER CTX',locator='User-approved education wording; portfolio context education sections',kind='Personal background')],silence=2)

